c.python:
class Solution:
    def maximumXOR(self, nums: List[int]) -> int:
        ans = 0
        for x in nums:
            ans |= x
        return ans

c.cpp:
class Solution {
public:
    int maximumXOR(vector<int>& nums) {
        int ans = 0;
        for (int x : nums) ans |= x;
        return ans;
    }
};

